let c = (await tools.read({ file_path: "D:\\lean\\tmp\\sheaf\\xif\\paper\\S1960QPilotAnchorActual.lean" })).lines.map(l=>l.text).join("\n");
const mark = `not asserted to be the paper's q-pilot strip.  Hence the first missing is a
definition, not a proposition:`;
const repl = `not asserted to be the paper's q-pilot strip.  The canonical q-pilot-object
constructor \`paperQPilotObjectActualOfCanonical\` (\`QPilotCanonicalConstruction\`)
likewise takes the F-prime-strip as a parameter and then applies
\`SourceFTimesMuPrimeStrip.canonical\`; it does not construct a \`q_v\`-determined
paper strip.  Hence the first missing is a definition, not a proposition:`;
if (!c.includes(mark)) throw new Error("mark not found");
c = c.replace(mark, repl);
await tools.write({ file_path: "D:\\lean\\tmp\\sheaf\\xif\\paper\\S1960QPilotAnchorActual.lean", content: c });
console.log("edited, bytes", c.length);
const r = await tools.pwsh({ description: "Final rebuild of S1960 olean", command: "lake env lean -j1 -R \"D:\\lean\" -o .lake/build/lib/lean/tmp/sheaf/xif/paper/S1960QPilotAnchorActual.olean tmp/sheaf/xif/paper/S1960QPilotAnchorActual.lean 2>&1 | Tee-Object -FilePath tmp/sheaf/xif/paper/S1960.olean.log | Out-String; $e=$LASTEXITCODE; \"EXIT=$e\"", workdir: "D:\\lean", timeoutMs: 900000 });
console.log(r.kind === "foreground" ? r.stdout.text.slice(-2500) + "\nSTDERR:\n" + r.stderr.text : JSON.stringify(r));
", "description": "Add canonical-constructor note and rebuild"}

